mapper.select:
SELECT user_info.*, ( SELECT GROUP_CONCAT( p.`name` ) FROM post p WHERE FIND_IN_SET( p.id, user_info.postIds )) AS posts, ( SELECT GROUP_CONCAT( pg.`name` ) FROM post_group pg WHERE FIND_IN_SET( pg.id, user_info.groupIds )) AS postGroups, ( SELECT GROUP_CONCAT( c.`name` ) FROM company c WHERE FIND_IN_SET( c.id, user_info.companyIds )) AS companys FROM ( SELECT su.id AS userId, se.id AS employeeId, su.username AS username, se.`name` AS name, sup.company_ids as companyIds, sup.post_ids as postIds, sup.group_ids as groupIds, se.birthday, se.address, su.mobile_phone AS mobilePhone, su.email, su.gender, su.description, se.province, se.city, se.country, se.origin, se.identity, se.work_status AS workStatus, se.bonus_coefficient as bonusCoefficient, se.work_amount as workAmount, se.work_type AS workType, se.contract_signing_date AS contractSigningDate, se.entry_date AS entryDate, se.graduated_school AS graduatedSchool, se.education AS education, se.leave_time AS leaveTime, se.title, se.post_level AS postLevel, se.emergency_contact AS emergencyContact, se.emergency_contact_phone AS emergencyContactPhone, se.discount, se.photo, se.diploma_photo AS diplomaPhoto, se.work_number AS workNumber FROM sys_user su LEFT JOIN sys_employee se ON su.id = se.user_id LEFT JOIN ( SELECT sup.user_id, GROUP_CONCAT( DISTINCT any_value(sup.company_id) SEPARATOR ',' ) AS company_ids, GROUP_CONCAT( DISTINCT any_value(sup.post_id) SEPARATOR ',' ) AS post_ids, GROUP_CONCAT( DISTINCT any_value(sup.group_id) SEPARATOR ',' ) AS group_ids FROM sys_user_post sup GROUP BY sup.user_id ) sup ON su.id = sup.user_id ) user_info where user_info.userId in
#{userId}
order by user_info.workStatus asc, user_info.userId desc

SELECT user_info.*, ( SELECT GROUP_CONCAT( p.`name` ) FROM post p WHERE FIND_IN_SET( p.id, user_info.postIds )) AS posts, ( SELECT GROUP_CONCAT( pg.`name` ) FROM post_group pg WHERE FIND_IN_SET( pg.id, user_info.groupIds )) AS postGroups, ( SELECT GROUP_CONCAT( c.`name` ) FROM company c WHERE FIND_IN_SET( c.id, user_info.companyIds )) AS companys FROM ( SELECT su.id AS userId, se.id AS employeeId, su.username AS username, se.`name` AS name, se.pinyin as pinyin, sup.company_ids as companyIds, sup.post_ids as postIds, sup.group_ids as groupIds, se.birthday, se.address, su.mobile_phone AS mobilePhone, su.email, su.gender, su.gender as genderValue, su.description, se.province, se.city, se.country, se.origin, se.identity, se.work_status AS workStatus, se.bonus_coefficient as bonusCoefficient, se.work_amount as workAmount, se.work_type AS workType, se.contract_signing_date AS contractSigningDate, se.entry_date AS entryDate, se.graduated_school AS graduatedSchool, se.education AS education, se.leave_time AS leaveTime, se.title, se.post_level AS postLevel, se.emergency_contact AS emergencyContact, se.emergency_contact_phone AS emergencyContactPhone, se.discount, see.discount_rate AS discountRate, see.discount_amount AS discountAmount, se.photo, se.diploma_photo AS diplomaPhoto, se.work_number AS workNumber, se.category, se.registration, se.permanent_address AS permanentAddress, se.graduation_time AS graduationTime, se.study_major AS studyMajor, se.last_job AS lastJob, se.probation_period_time AS probationPeriodTime FROM sys_user su LEFT JOIN sys_employee se ON su.id = se.user_id LEFT JOIN sys_employee_ext see ON see.user_id=su.id LEFT JOIN ( SELECT sup.user_id, GROUP_CONCAT( DISTINCT any_value(sup.company_id) SEPARATOR ',' ) AS company_ids, GROUP_CONCAT( DISTINCT any_value(sup.group_id) SEPARATOR ',' ) AS group_ids, GROUP_CONCAT( DISTINCT any_value(sup.post_id) SEPARATOR ',' ) AS post_ids FROM sys_user_post sup
and sup.user_id = #{queryForm.userId}
and sup.company_id in
#{item}
and sup.group_id in
#{item}
and sup.post_id in
#{item}
GROUP BY sup.user_id ) sup ON su.id = sup.user_id ) user_info
and user_info.userId = #{queryForm.userId}
and
FIND_IN_SET(#{item}, user_info.companyIds)
and
FIND_IN_SET(#{item}, user_info.groupIds)
and
FIND_IN_SET(#{item}, user_info.postIds)
and CONCAT(IFNULL(user_info.name, ''), IFNULL(user_info.mobilePhone, ''), IFNULL(user_info.pinyin, '')) like concat('%', #{queryForm.keyWord} ,'%')
and IFNULL(user_info.name, '') like concat('%', #{queryForm.userName} ,'%')
and user_info.workStatus in
#{item}
and user_info.userId in
#{item}
and user_info.name = #{queryForm.name}
order by user_info.workStatus asc, user_info.userId desc

SELECT t2.user_id as userId, t2.name, t4.id AS companyIds, t4.name AS companys, t2.work_status AS workStatus, t2.leave_time AS leaveTime FROM sys_user t1 LEFT JOIN sys_employee t2 ON t1.id = t2.user_id LEFT JOIN (select company_id,user_id from sys_user_post group by company_id,user_id) t3 ON t1.id = t3.user_id LEFT JOIN company t4 ON t3.company_id = t4.id
and IFNULL(t2.name, '') like concat('%', #{queryForm.userName} ,'%')
and t4.id in
#{item}
and t2.work_status in
#{item}
and t2.user_id in
#{item}
and CONCAT(t2.user_id,',',t4.id) in
#{item}
order by t1.id desc
